export interface StudioCrewMember {
  position: string
  name: string
}

export interface StudioProfileInfo {
  name?: string
  officers?: string[]
  founded?: string
  addressJp?: string
  addressEn?: string
  mapsUrl?: string
  mail?: string
  capital?: string
}

export interface ElasticEditorialAboutProps {
  /**
   * Main title words displayed in the giant vertical typographic stack.
   * Defaults to ["ABOUT", "KINETIC", "STUDIO"].
   */
  titleWords?: string[]
  /**
   * Studio manifesto tagline displayed beneath the titles.
   */
  tagline?: string
  /**
   * Japanese studio philosophy statement.
   */
  statementJp?: string
  /**
   * English studio philosophy statement.
   */
  statementEn?: string
  /**
   * Studio crew list.
   */
  crews?: StudioCrewMember[]
  /**
   * Industry awards list.
   */
  awards?: Array<{ name: string; width: number; src: string }>
  /**
   * Studio profile metadata.
   */
  profile?: StudioProfileInfo
  /**
   * Background image URL for WebGL parabolic warp.
   * Defaults to embedded authentic studio office backdrop.
   */
  backgroundImageSrc?: string
  /**
   * Enable real-time WebGL2 parabolic warping responding to scroll inertia.
   * Defaults to true.
   */
  enableWarpShader?: boolean
  /**
   * Root container height. Must be a definite length (e.g. "100svh").
   */
  height?: string
  /**
   * Extra root container classes.
   */
  className?: string
}

